  "tips.modal.title": "आज की सलाह",
  "tips.modal.gotIt": "समझ गया",
  "tips.priceFloor": "हमेशा अपनी लागत सीमा से ऊपर कीमत रखें — कच्चा माल, आपका समय और प्लेटफ़ॉर्म शुल्क — मंदी के महीने में भी।",
  "tips.trackIncome": "हर बिक्री दर्ज करें, चाहे वह छोटी ही क्यों न हो। एक सरल आय रिकॉर्ड आपको कमज़ोर मौसम की योजना बनाने और ऋण के लिए कमाई साबित करने में मदद करता है।",
  "tips.bulkOrders": "थोक और संस्थागत ऑर्डर नियमित और पहले से भुगतान देते हैं। अपनी क्षमता और डिलीवरी समय अपडेट रखें ताकि खरीदार आपको ढूंढ सकें।",
  "tips.photoQuality": "साफ़, अच्छी रोशनी वाली और कई कोणों से ली गई तस्वीरों वाली लिस्टिंग जल्दी बिकती हैं। प्राकृतिक धूप फ्लैश से बेहतर काम करती है।",
  "tips.respondFast": "जब आप एक दिन के भीतर सवालों का जवाब देते हैं, तो खरीदार ऑर्डर पूरा करने की अधिक संभावना रखते हैं।",
  "tips.saveSavings": "हर भुगतान का एक छोटा हिस्सा बचत के रूप में अलग रखें — 5% भी जुड़कर ऑर्डरों के बीच आपकी मदद करता है।",
  "tips.giPremium": "GI टैग मूल स्थान का प्रमाण है जिस पर खरीदार भरोसा करते हैं। प्रमाणित उत्पादों की कीमत अक्सर ज़्यादा रखी जा सकती है — अपनी कीमत कम मत आंकिए।",
  "tips.restockEarly": "कच्चा माल खत्म होने से पहले ही फिर से मंगवाना शुरू करें, खासकर त्योहार और शादी के मौसम से पहले जब मांग बढ़ जाती है।",
  "tips.clusterSupport": "आपके क्लस्टर समन्वयक थोक सामग्री खरीद और प्रशिक्षण में मदद कर सकते हैं — किसी समस्या के गंभीर होने से पहले ही संपर्क करें।",
  "tips.storySells": "खरीदार कहानी वाले उत्पादों के लिए अधिक भुगतान करते हैं। अपनी लिस्टिंग में अपनी तकनीक या शिल्प के इतिहास के बारे में एक छोटा नोट जोड़ें।",
  "badges.empty": "अभी कोई बैज नहीं मिला है। बैज अर्जित करने के लिए अपनी पहली वस्तु सूचीबद्ध करें।",
