  "pdp.care.dryClean": "केवल ड्राई क्लीन करें। मलमल में मोड़कर, सीधी धूप से दूर रखें।",
  "pdp.care.handWash": "ठंडे पानी और हल्के साबुन से धीरे से हाथ से धोएँ। छाँव में सुखाएँ।",
  "pdp.care.wipe": "मुलायम सूखे कपड़े से पोंछें। सावधानी से रखें; डिशवॉशर में न डालें।",
  "pdp.care.polish": "कभी-कभी सूखे कपड़े से चमकाएँ। पानी और अम्लीय क्लीनर से बचाएँ।",
  "pdp.care.dry": "नमी से दूर रखें। मुलायम ब्रश से धूल हटाएँ।",
  "pdp.care.frame": "काँच के पीछे फ्रेम करें। सीलन वाली दीवारों और सीधी धूप से बचाएँ।",
  "pdp.care.default": "सावधानी से रखें। मुलायम सूखे कपड़े से धीरे से साफ़ करें।",
  "pdp.review.1.title": "तस्वीरों से भी बेहतर",
  "pdp.review.1.body": "{craft} का काम सामने से और भी बारीक है। छोटी-छोटी असमानताएँ बताती हैं कि यह हाथ से बना है। बहुत सावधानी से पैक किया गया।",
  "pdp.review.2.title": "हर रुपये के लायक",
  "pdp.review.2.body": "यह जानकर कि पैसा सीधे {artisan} को जाता है, फ़ैसला आसान हो गया। संग्रहालय जैसी गुणवत्ता।",
  "pdp.review.3.title": "सुंदर, थोड़ी देर से आया",
  "pdp.review.3.body": "अनुमान से तीन दिन बाद पहुँचा, पर कारीगर ने संदेश भेजकर कारण बताया। वस्तु अपने आप में शानदार है।",
  "pdp.review.4.title": "सील जाँची, सब असली",
  "pdp.review.4.body": "पहुँचने पर प्रमाणिकता रिकॉर्ड जाँचा और वह लिस्टिंग से पूरी तरह मेल खाता था। आख़िरकार ऑनलाइन शिल्प खरीद पर भरोसा हुआ।",
  "pdp.review.5.title": "अच्छा, पर आकार जाँच लें",
  "pdp.review.5.body": "बढ़िया कारीगरी, पर उम्मीद से छोटा है। ऑर्डर से पहले विवरण तालिका में माप पढ़ लें।",
  "pdp.qa.1.q": "क्या यह हाथ से बना है या मशीन से?",
  "pdp.qa.1.a": "पूरी तरह हाथ से बना है। जीआई टैग और प्रमाणिकता सील दोनों तकनीक की पुष्टि करते हैं।",
  "pdp.qa.2.q": "क्या मैं अलग रंग माँग सकता/सकती हूँ?",
  "pdp.qa.2.aMto": "हाँ, ऑर्डर पर बनने वाली वस्तुओं में बदलाव हो सकता है — ऑर्डर नोट में लिख दें।",
  "pdp.qa.2.aReady": "यह तैयार स्टॉक है, इसलिए रंग वैसे ही हैं जैसे दिखाए गए हैं। कस्टम ऑर्डर के लिए कारीगर को संदेश भेजें।",
  "pdp.qa.3.q": "इसे भेजने के लिए कैसे पैक किया जाता है?",
  "pdp.qa.3.a": "कपड़े में, फिर बबल रैप में लपेटकर दोहरी दीवार वाले डिब्बे में। नाज़ुक वस्तुओं के लिए विशेष क्रेट।",
  "pdp.qa.4.q": "क्या धोने के बाद रंग फीके पड़ेंगे?",
  "pdp.qa.4.a": "प्राकृतिक रंग सालों में थोड़े हल्के होते हैं, जो स्वाभाविक है। रंग बनाए रखने के लिए देखभाल निर्देशों का पालन करें।",
  "pdp.storefront.bio": "{name} {district} में {craft} का काम करते हैं और सीधे खरीदारों को बेचते हैं।",
