  "caseStudies.dhamadka-ajrakh.title": "धमादका के कीमियागर",
  "caseStudies.dhamadka-ajrakh.subtitle": "16-चरणीय प्राकृतिक इंडिगो कीचड़-प्रतिरोध को पुनर्जीवित करना और 42 मास्टर परिवारों के लिए जीवनयापन मजदूरी सुरक्षित करना।",
  "caseStudies.dhamadka-ajrakh.cluster": "कच्छ कारीगर सामूहिक",
  "caseStudies.dhamadka-ajrakh.region": "धमडका, गुजरात",
  "caseStudies.dhamadka-ajrakh.giTag": "जीआई-72 (कच्छ अजरख)",
  "caseStudies.dhamadka-ajrakh.metrics.0.label": "कारीगरों की आय में वृद्धि",
  "caseStudies.dhamadka-ajrakh.metrics.0.value": "+337% (हिन्दी)",
