  "caseStudies.bastar-lost-wax.rows.2.after": "28 आदिवासी युवाओं ने 4,000 साल पुरानी मोम ढलाई में प्रशिक्षण लिया",
  "caseStudies.bastar-lost-wax.rows.3.dimension": "पहचान पहचान",
  "caseStudies.bastar-lost-wax.rows.3.before": "सरकारी एमएसएमई कार्ड के बिना गुमनाम आदिवासी निर्माता",
  "caseStudies.bastar-lost-wax.rows.3.after": "100% पहचान और पीएम विश्वकर्मा सत्यापित आईडी कार्ड",
  "caseStudies.bastar-lost-wax.problem": "अस्थिर तांबे और जस्ता स्क्रैप मूल्य निर्धारण ने आदिवासी ढोकरा मूर्तिकारों के लिए कच्चे मोम, मिट्टी और ढलाई धातुओं का खर्च वहन करना लगभग असंभव बना दिया है, जिससे मानवता की सबसे पुरानी अलौह ढलाई वंशावली में से एक के खत्म होने का खतरा पैदा हो गया है।",
  "caseStudies.bastar-lost-wax.intervention": "मंच ने संस्थागत शिखर खरीद किट द्वारा समर्थित कच्चे माल इन्वेंट्री क्रेडिट की शुरुआत की। मूर्तिकार अपने कारीगर ऐप पर पिघले हुए पानी को रिकॉर्ड करते हैं, जो बेदाग बेल धातु मिश्र धातु को साबित करता है।",
  "caseStudies.bastar-lost-wax.impact": "कोंडागांव भट्ठों में 28 नये आदिवासी प्रशिक्षु शामिल हुए हैं। बस्तर की खोई हुई मोम की मूर्तियां अब दुनिया भर में प्रमुख संस्थागत लॉबी और राजनयिक उपहारों की शोभा बढ़ा रही हैं।",
  "caseStudies.bastar-lost-wax.quote.text": "हमारे पूर्वज साल के जंगलों से प्राप्त मोम का उपयोग करते थे। कलाकृति यह सुनिश्चित करती है कि हमारी भट्टियाँ कर्ज के डर के बिना अगली पीढ़ी के लिए चमकती रहें।",
  "caseStudies.bastar-lost-wax.quote.author": "बुधेश्वर घड़वा",
  "caseStudies.bastar-lost-wax.quote.role": "वरिष्ठ सिरे-पर्ड्यू मेटलवर्कर, कोंडागांव",
